// Generated by tabmill (templates/extension/maps-overlay) — do not edit (ADR-0008).
// Toolbar click → inject the overlay into this tab only (activeTab + scripting; no host
// permissions). A second click removes it. Content scripts can't open tabs, so the overlay
// asks for its own extension pages via `{ type: "tabmill:open-page", path }`.
export default defineBackground(() => {
  browser.runtime.onMessage.addListener((message: unknown) => {
    const m = message as { type?: string; path?: string };
    if (m?.type !== "tabmill:open-page" || !m.path?.startsWith("/") || m.path.includes("//")) return;
    void browser.tabs.create({ url: browser.runtime.getURL(m.path as "/") });
  });
  browser.action.onClicked.addListener((tab) => {
    if (tab.id === undefined) return;
    browser.scripting
      .executeScript({ target: { tabId: tab.id }, files: ["/content-scripts/overlay.js"] })
      .catch((e: unknown) => console.error(e));
  });
});
